code:
db.orders.find({ status: "shipped" })

db.orders.find({ total: { $gt: 100 } })

db.orders.find({
  total: { $gte: 100, $lte: 500 }
})

db.orders.find({
  status: { $in: ["shipped", "delivered"] }
})

// implicit AND
db.orders.find({
  status: "shipped", total: { $gt: 100 }
})

// explicit $or
db.orders.find({
  $or: [
    { status: "cancelled" },
    { total: { $lt: 10 } }
  ]
})

// include only these fields
db.orders.find(
  { status: "shipped" },
  { customerName: 1, total: 1, _id: 0 }
)

// exclude one field, keep the rest
db.orders.find(
  { status: "shipped" },
  { internalNotes: 0 }
)
